const repo = ($vars.GITHUB_REPO || 'n8n-io/n8n').trim();
if (!repo.includes('/')) {
  throw new Error('GITHUB_REPO must use owner/repo format, for example n8n-io/n8n');
}
const [owner, name] = repo.split('/');
const now = new Date();
const since = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const language = (($vars.LANGUAGE || 'EN') + '').toUpperCase();
const deliveryMode = (($vars.DELIVERY_MODE || 'slack') + '').toLowerCase();
const destinationChannel = $vars.DESTINATION_CHANNEL || '';
return [{
  json: {
    repo,
    owner,
    name,
    since: since.toISOString(),
    until: now.toISOString(),
    language: ['EN', 'FR'].includes(language) ? language : 'EN',
    delivery_mode: ['slack', 'discord'].includes(deliveryMode) ? deliveryMode : 'slack',
    destination_channel: destinationChannel
  }
}];

const cfg = $('Build Weekly Run Config').first().json;
return [{
