={{ {
  query: `query RepoWeekly($owner: String!, $name: String!, $since: GitTimestamp!) {
    repository(owner: $owner, name: $name) {
      defaultBranchRef {
        target {
          ... on Commit {
            history(first: 100, since: $since) {
              nodes { oid committedDate messageHeadline url author { name email user { login } } }
            }
          }
        }
      }
      issues(first: 100, states: CLOSED, orderBy: { field: UPDATED_AT, direction: DESC }) {
        nodes { number title closedAt url labels(first: 10) { nodes { name } } author { login } }
      }
      pullRequests(first: 100, states: MERGED, orderBy: { field: UPDATED_AT, direction: DESC }) {
        nodes { number title mergedAt url additions deletions changedFiles author { login } }
      }
    }
  }`,
  variables: { owner: $json.owner, name: $json.name, since: $json.since }
} }}

