const cfg = $('Build Weekly Run Config').first().json;
const response = $input.first().json;
if (response.errors) {
  throw new Error('GitHub GraphQL error: ' + JSON.stringify(response.errors));
}
const repository = response.data?.repository;
if (!repository) {
  throw new Error('GitHub response did not include repository data. Check GITHUB_REPO and GITHUB_TOKEN.');
}
const sinceMs = new Date(cfg.since).getTime();
const commits = (repository.defaultBranchRef?.target?.history?.nodes || []).map(c => ({
  message: c.messageHeadline,
  author: c.author?.user?.login || c.author?.name || 'unknown',
  date: c.committedDate,
  url: c.url
}));
const closed_issues = (repository.issues?.nodes || [])
  .filter(i => i.closedAt && new Date(i.closedAt).getTime() >= sinceMs)
  .map(i => ({
    number: i.number,
    title: i.title,
    url: i.url,
    closed_at: i.closedAt,
    labels: (i.labels?.nodes || []).map(l => l.name)
  }));
const merged_prs = (repository.pullRequests?.nodes || [])
  .filter(p => p.mergedAt && new Date(p.mergedAt).getTime() >= sinceMs)
  .map(p => ({
    number: p.number,
    title: p.title,
    author: p.author?.login || 'unknown',
    url: p.url,
    merged_at: p.mergedAt,
    additions: p.additions,
    deletions: p.deletions,
    changed_files: p.changedFiles
  }));
return [{ json: { ...cfg, commits, closed_issues, merged_prs, source: 'github-graphql' } }];

const data = $input.first().json;
const heading = data.language === 'FR'
  ? 'Tu es un tech lead qui rédige un résumé hebdomadaire clair pour une équipe produit.'
  : 'You are a tech lead writing a concise weekly development narrative for a product team.';
const instructions = data.language === 'FR'
  ? 'Rédige en français. Structure: Highlights, Risques/Blocages, Détails clés, Prochaines étapes. Reste sous 500 mots.'
  : 'Write in English. Structure: Highlights, Risks/Blockers, Key Details, Next Steps. Keep it under 500 words.';
const compact = {
  repo: data.repo,
  week: { since: data.since.slice(0, 10), until: data.until.slice(0, 10) },
  counts: {
    commits: data.commits.length,
    closed_issues: data.closed_issues.length,
    merged_prs: data.merged_prs.length
  },
  commits: data.commits.slice(0, 30),
  closed_issues: data.closed_issues.slice(0, 30),
  merged_prs: data.merged_prs.slice(0, 30)
};
const prompt = `${heading}\n\n${instructions}\n\nWeekly GitHub activity JSON:\n${JSON.stringify(compact, null, 2)}`;
return [{
  json: {
    ...data,
    claude_request: {
      model: 'claude-sonnet-4-20250514',
      max_tokens: 1400,
      messages: [{ role: 'user', content: prompt }]
    }
  }
}];

const base = $('Prepare Claude Request').first().json;
const response = $input.first().json;
const summary = response.content?.[0]?.text || response.output_text || 'Claude API returned no summary text.';
return [{ json: { ...base, summary, generated_by: 'claude-api' } }];

const data = $input.first().json;
const title = data.language === 'FR'
  ? `Résumé hebdomadaire — ${data.repo}`
  : `Weekly Dev Summary — ${data.repo}`;
const period = `${data.since.slice(0, 10)} → ${data.until.slice(0, 10)}`;
const footer = data.language === 'FR'
  ? `_Généré par n8n + Claude (${data.generated_by})_`
  : `_Generated by n8n + Claude (${data.generated_by})_`;
const body = `*${title}*\n${period}\n\n${data.summary}\n\n${footer}`;
const mode = data.delivery_mode || 'slack';
let delivery_url = '';
let payload = {};
if (mode === 'discord') {
  delivery_url = $vars.DISCORD_WEBHOOK_URL;
  payload = {
    username: 'Weekly Dev Summary',
    embeds: [{
      title,
      description: `${period}\n\n${data.summary}`.slice(0, 4000),
      color: 5814783,
      footer: { text: `n8n + Claude · ${data.generated_by}` }
    }]
  };
} else {
  delivery_url = $vars.SLACK_WEBHOOK_URL;
  payload = {
    text: body,
    channel: data.destination_channel || undefined,
    blocks: [
      { type: 'header', text: { type: 'plain_text', text: title.slice(0, 150) } },
      { type: 'context', elements: [{ type: 'mrkdwn', text: period }] },
      { type: 'section', text: { type: 'mrkdwn', text: data.summary.slice(0, 2900) } },
      { type: 'context', elements: [{ type: 'mrkdwn', text: footer }] }
    ]
  };
}
if (!delivery_url && data.generated_by !== 'dry-run') {
  throw new Error(`Missing webhook URL for DELIVERY_MODE=${mode}. Set SLACK_WEBHOOK_URL or DISCORD_WEBHOOK_URL.`);
}
return [{ json: { ...data, title, body, delivery_url, payload } }];
